def runs_for_grid(grid, fg):
 by=defaultdict(set)
 for r,c in zip(*np.where(grid==fg)): by[int(r+c)].add(int(r-c))
 runs=[]
 for d,vs in by.items():
  vals=sorted(vs)
  # actual samples advance by 2 for contiguous diagonal, treat gap >2 as separate
  cur=[vals[0]]
  for v in vals[1:]:
   if v-cur[-1]<=2: cur.append(v)
   else:
    runs.append((d,min(cur),max(cur),len(cur)));cur=[v]
  runs.append((d,min(cur),max(cur),len(cur)))
 return runs
def fill_local(grid, fg, fill=2, minlen=2):
 g=grid.copy(); runs=[x for x in runs_for_grid(grid,fg) if x[3]>=minlen]
 # discretize v integer and find all active distinct d-lines; if same d multiple segments can have disjoint intervals
 # for every v, select active segments. if a line has multiple active segments at same v, same d duplicate; collapse d
 for v in range(-grid.shape[0]*2,grid.shape[1]*2+1):
  active=sorted(set(d for d,lo,hi,n in runs if lo<=v<=hi))
  for d1,d2 in zip(active,active[1:]):
   for d in range(d1+1,d2):
    if (d+v)%2: continue
    r=(d+v)//2;c=(d-v)//2
    if 0<=r<g.shape[0] and 0<=c<g.shape[1] and g[r,c]!=fg:g[r,c]=fill
 return g
